{
  "summary": "On 16 March 2025 one edge-gateway pod (edge-gateway-01) kept serving an expired certificate because it was not restarted after the secret renewal, causing TLS failures for about one third of partner calls and near‑zero request rate on that pod.",
  "likely_cause": "Pod edge-gateway-01 missed the required restart after the certificate secret was renewed, so Envoy continued using the old certificate in memory.",
  "confidence": "high",
  "claims": [
    {
      "text": "edge-gateway-01 presented a certificate whose notAfter was 2025-03-16 10:15 UTC while the other pods presented the renewed one.",
      "evidence_ids": ["INC-0023#0"],
      "quote": "edge-gateway-01 presents a certificate whose notAfter is 2025-03-16 10:15 UTC."
    },
    {
      "text": "Envoy reads the certificate files only at startup; a renewed Secret takes effect only after a pod restart (e.g., rollout restart).",
      "evidence_ids": ["RB-025#0"],
      "quote": "Envoy reads those files when it starts, so a renewed Secret takes effect only after `kubectl -n platform rollout restart deploy/edge-gateway`."
    },
    {
      "text": "The renewal note said to restart every edge pod, but a manual delete sequence missed restarting edge-gateway-01.",
      "evidence_ids": ["INC-0023#1"],
      "quote": "the original pod behind edge-gateway-01 never was. Envoy reads the certificate only at start, so it kept the old one in memory for a month."
    }
  ],
  "next_checks": [
    "Verify that all edge-gateway pods have been restarted after the last certificate renewal.",
    "Confirm that future renewals use `kubectl rollout restart` instead of manual pod deletions.",
    "Run `openssl s_client` against each pod to ensure they all present the new certificate."
  ]
}
